let ctx;
let centerX, centerY;
let hexagons = [];
let palette = ['#fca9ce', '#EA4263', '#FFCF52', '#3083DC', '#9fa3e3', '#FE8074', '#575782'];

function setup() {
	createCanvas(675, 1200);
	colorMode(HSB, 360, 100, 100, 100);
	ctx = drawingContext;
	centerX = width / 2;
	centerY = height / 2;
	createHoneycomb();
	background('#fffde7');
	for (let i of hexagons) {
		let sclX = random([-1, 1]);
		let ang = int(random(6)) * (TAU / 6);
		let shapeType = int(random(16));
		drawSomething(i.x, i.y, i.w * 0.8, i.a + ang, sclX, shapeType);
	}

}

function draw() {
  // === Variant 1: Neon Kinetic Glitch Modification ===
  dynamicShift = sin((frameCount * speedMult) * 0.08) * 40;


}

function createHoneycomb() {
	let hexW = width * 0.15
	;
	let hexH = hexW * sqrt(3) / 2;
	let y = -hexH;
	let yCounter = 0;

	while (y < height + hexW) {
		let x = -hexW;
		let offsetX = 0;
		if (yCounter % 2 === 0) {
			offsetX = hexH / 2;
		}
		while (x < width + hexW) {
			hexagons.push({ x: x + offsetX, y: y, w: hexW, h: hexH, a: PI / 2 });
			x += hexH;
		}
		y += hexW * 0.75;
		yCounter++;
	}
}


function drawSomething(x, y, w, ang, sclX, shapeType) {
	let h = w * sqrt(3) / 2;;
	let colors = shuffle([...palette], true);
	let stClr = colors[2];
	let thisckness = w * 0.05

	push();
	translate(x, y);
	scale(sclX, 1);
	rotate(ang);
	noStroke();
	strokeWeight(thisckness);
	fill(colors[0]);
	if (shapeType === 0) {
		circle(0, 0, w * 0.6);

		stroke(stClr);
		line(w * 0.2, 0, w * 0.5, 0);
		rotate(PI * 0.15);
		line(w * 0.2, 0, w * 0.4, 0);
	}
	else if (shapeType === 1) {
		beginShape();
		vertex(-w / 4, -h / 2);
		vertex(0, 0);
		vertex(-w / 4, h / 2);
		vertex(-w / 2, 0);
		endShape();

		noFill();
		stroke(stClr);
		beginShape();
		vertex(-w / 8, -h / 2);
		vertex(w / 8, 0);
		vertex(-w / 8, h / 2);
		endShape();
		beginShape();
		vertex(0, -h / 2);
		vertex(w / 4, 0);
		vertex(0, h / 2);
		endShape();
	}
	else if (shapeType === 2) {
		circle(0, -h * 0.25, w * 0.25);

		noFill();
		stroke(stClr);
		arc(0, -h / 4, h / 2, h / 2, PI * 0.5, PI * 2.1);
		arc(0, h / 4, h / 2, h / 2, -PI * 0.5, PI * 0.6);
	}
	else if (shapeType === 3) {
		beginShape();
		vertex(w / 2, 0);
		vertex(w / 4, h / 2);
		vertex(-w / 4, h / 2);
		endShape();

		noFill();
		stroke(stClr);
		beginShape();
		vertex(w / 4, h / 2);
		vertex(-w / 4, h / 2);
		vertex(-w / 2, 0);
		endShape();
	}
	else if (shapeType === 4) {
		rect(0, h / 8, w / 2, h / 4);

		noFill();
		stroke(stClr);
		arc(-w / 4, 0, w / 2, w / 2, -PI / 2, 0);
		arc(w / 4, 0, w / 2, w / 2, PI, PI * 1.5);
		line(0, 0, 0, h / 2);
	}
	else if (shapeType === 5) {
		circle(-w / 4, 0, w * 0.35);
		fill(colors[1]);
		circle(w * 0.1, 0, w * 0.2);

		noFill();
		stroke(stClr);
		line(w / 4, h / 2, -w / 4, h / 2);
		line(-w / 4, 0, 0, h / 2);
	}
	else if (shapeType === 6) {
		arc(0, 0, h, h, PI, TAU);
		fill(colors[1]);
		beginShape();
		vertex(-w * 0.2, h * 0.3);
		vertex(0, 0);
		vertex(w * 0.2, h * 0.3);
		endShape();

		noFill();
		stroke(stClr);
		beginShape();
		vertex(-w * 0.2, h * 0.1);
		vertex(0, -h * 0.2);
		vertex(w * 0.2, h * 0.1);
		endShape();
	}
	else if (shapeType === 7) {
		for (let i = 0; i < 2; i++) {
			if (i == 1) {
				fill(colors[1]);
			}

			beginShape();
			vertex(-w / 4, -h / 2);
			vertex(0, 0);
			vertex(-w / 4, h / 2);
			vertex(-w / 2, 0);
			endShape(CLOSE);
			rotate(TAU / 3);
		}
	}
	else if (shapeType === 8) {
		circle(0, 0, h * 0.8);
		fill(colors[1]);
		circle(w * 0.16, 0, h * 0.3);
	}
	else if (shapeType === 9) {
		beginShape();
		vertex(-w / 2, 0);
		vertex(-w / 4, -h / 2);
		vertex(-w / 4, h / 2);
		endShape();
		fill(colors[1]);
		beginShape();
		vertex(0, 0);
		vertex(w / 4, 0);
		vertex(0, h / 2);
		endShape();
	}
	else if (shapeType === 10) {
		beginShape();
		vertex(-w / 4, h / 2);
		vertex(-w / 4, -h / 2);
		vertex(w / 4, -h / 2);
		endShape();
		fill(colors[1]);
		circle(-w * 0.25, h * 0.2, h * 0.3);
	}
	else if (shapeType === 11) {
		beginShape();
		vertex(0, 0);
		vertex(-w / 4, h / 2);
		vertex(w / 4, h / 2);
		endShape();

		noFill();
		stroke(stClr);
		beginShape();
		vertex(-w / 8, -h / 4);
		vertex(-w / 8 * 3, h / 4);
		vertex(w / 8, h / 4);
		endShape();
	}
	else if (shapeType === 12) {
		arc(-w / 8, -h / 4, h / 2, h / 2, (TAU / 6), (TAU / 6) * 4);
		fill(colors[1]);
		arc(w / 8, h / 4, h / 2, h / 2, (TAU / 6) * 4, (TAU / 6));
		noFill();
		stroke(stClr);
		line(-w / 4, -h / 2, w / 4, h / 2);
	}
	else if (shapeType === 13) {
		circle(0, -h / 16 * 5, w * 0.2);
		circle(0, h / 16 * 5, w * 0.2);
		noFill();
		stroke(stClr);
		beginShape();
		vertex(w / 4, -h / 2);
		vertex(-w / 4, -h / 2);
		vertex(w / 4, h / 2);
		vertex(w / 4, h / 2);
		vertex(-w / 4, h / 2);
		endShape();
	}
	else if (shapeType === 14) {
		beginShape();
		vertex(-w / 8 * 3, h / 4);
		vertex(w / 8 * 3, h / 4);
		vertex(w / 4, h / 2);
		vertex(-w / 4, h / 2);
		endShape();
		fill(colors[1]);
		circle(0, -h * 0.2, w * 0.2);

		stroke(stClr);
		line(0, -h * 0.2, 0, h * 0.3);
	}
	else if (shapeType === 15) {
		beginShape();
		for (let i = 0; i < 6; i++) {
			let a = map(i, 0, 6, 0, TAU);
			let r = h * 0.25;
			vertex(r * cos(a), r * sin(a));
		}
		endShape();

		stroke(stClr);
		line(-w * 0.15, h * 0.3, w * 0.15, h * 0.3);
		line(-w * 0., h * 0.4, w * 0.2, h * 0.4);
	}
	pop();
}


